package dns
import("context";"fmt";"math";"strings";"sync";"time")
type ProbePolicy struct{FailureThreshold uint32 `json:"failure_threshold"`;SuccessThreshold uint32 `json:"success_threshold"`;MaxLatency time.Duration `json:"max_latency"`}
type ProbeState struct{Failures uint32 `json:"failures"`;Successes uint32 `json:"successes"`;Healthy bool `json:"healthy"`}
type ProbePolicyController struct{mu sync.Mutex;states map[string]ProbeState}
func NewProbePolicyController()*ProbePolicyController{return &ProbePolicyController{states:make(map[string]ProbeState)}}
func(p ProbePolicy)Validate()error{if p.FailureThreshold==0||p.FailureThreshold>1000||p.SuccessThreshold==0||p.SuccessThreshold>1000{return fmt.Errorf("probe thresholds must be between 1 and 1000")};if p.MaxLatency<=0||p.MaxLatency>60*time.Second{return fmt.Errorf("max latency must be between 1ns and 60s")};return nil}
func(c *ProbePolicyController)Observe(ctx context.Context,key string,result DNSProbeResult,policy ProbePolicy)(bool,error){if c==nil{return false,fmt.Errorf("probe policy controller is required")};if err:=policy.Validate();err!=nil{return false,err};if ctx==nil{return false,context.Canceled};if err:=ctx.Err();err!=nil{return false,err};key=strings.TrimSpace(key);if key==""||len(key)>256{return false,fmt.Errorf("probe policy key is invalid")};latencyValid:=result.Latency>=0&&!math.IsNaN(float64(result.Latency))&&!math.IsInf(float64(result.Latency),0);c.mu.Lock();defer c.mu.Unlock();if c.states==nil{c.states=make(map[string]ProbeState)};state:=c.states[key];if result.Reachable&&latencyValid&&result.Latency<=policy.MaxLatency{state.Failures=0;if state.Successes<^uint32(0){state.Successes++};if state.Successes>=policy.SuccessThreshold{state.Healthy=true}}else{state.Successes=0;if state.Failures<^uint32(0){state.Failures++};if state.Failures>=policy.FailureThreshold{state.Healthy=false}};c.states[key]=state;return state.Healthy,nil}
